    if (pRoom && pClient->pPlayer) UNITS_SetPlayerPortalFlags(pClient->pPlayer,
        UNITS_GetPlayerPortalFlags(pClient->pPlayer) |
        DUNGEON_GetPortalFlagFromLevelId(DUNGEON_GetLevelIdFromRoom(pRoom)));
